#!/usr/bin/env python3
from pwn import *
from base64 import b64encode, b64decode
import time
import sys

# Configure pwntools
context.log_level = 'warning'

def retry_connect():
    while True:
        try:
            return remote('crypto.chal.csaw.io', 6000, timeout=10)
        except Exception:
            time.sleep(1)
            continue

def get_fresh_banner(r):
    try:
        r.sendlineafter(b'>', b'1')
        r.sendlineafter(b'>', b'A' * 16)
        r.sendlineafter(b'>', b'1')
        data = r.recvuntil(b'\n\n').decode()
        return data.split('reads: ')[-1].strip()
    except Exception:
        return None

def check_padding(r, ct):
    try:
        r.sendlineafter(b'>', b'2')
        r.sendlineafter(b'>', ct)
        resp = r.recvline().decode()
        return 'Valid' in resp
    except Exception:
        return None

def get_block(ct, block_num):
    blocks = [ct[i:i+16] for i in range(0, len(ct), 16)]
    return blocks[block_num] if block_num < len(blocks) else None

def attack_byte(position, known_bytes=b''):
    r = retry_connect()
    ct_b64 = get_fresh_banner(r)
    if not ct_b64:
        return None, None

    ct = b64decode(ct_b64)
    target_block = get_block(ct, 2)  # Block containing flag

    byte_pos = 15 - len(known_bytes)
    pad_val = 16 - byte_pos

    for guess in range(256):
        try:
            attack_block = bytearray(16)
            attack_block[byte_pos] = guess

            modified = ct[:32] + bytes(attack_block) + target_block + ct[64:]
            modified_b64 = b64encode(modified)

            if check_padding(r, modified_b64):
                decrypted = guess ^ pad_val ^ target_block[byte_pos]
                r.close()
                return decrypted, True

            time.sleep(0.2)  # Rate limiting

        except Exception:
            r.close()
            return None, False

    r.close()
    return None, True

def poodle_attack():
    decrypted = b''
    retries = 0

    while len(decrypted) < 16:
        byte, completed = attack_byte(len(decrypted), decrypted)

        if byte is not None:
            decrypted = bytes([byte]) + decrypted
            print(f"[+] Decrypted bytes: {decrypted.hex()}")
            print(f"[+] ASCII: {decrypted}")

            # Check if we found the flag
            if b'flag{' in decrypted and b'}' in decrypted:
                flag_start = decrypted.index(b'flag{')
                flag_end = decrypted.index(b'}', flag_start) + 1
                return decrypted[flag_start:flag_end].decode()

            retries = 0

        elif completed:
            if retries > 5:
                return None
            retries += 1
            print(f"[-] Byte not found, retry {retries}/5")
            time.sleep(1)

        else:
            time.sleep(0.5)
            continue

    return None

if __name__ == '__main__':
    print("[*] Starting POODLE attack...")
    while True:
        try:
            flag = poodle_attack()
            if flag:
                print(f"[+] Found flag: {flag}")
                break
        except KeyboardInterrupt:
            print("\n[!] Attack interrupted")
            break
        except Exception as e:
            print(f"[-] Error: {e}")
            time.sleep(1)
            continue

