from pwn import *
from base64 import b64encode, b64decode
import time
import re

context.log_level = 'error'

class PoodleAttack:
    def __init__(self):
        self.host = 'crypto.chal.csaw.io'
        self.port = 6000
        self.block_size = 16

    def get_oracle(self):
        for _ in range(3):  # Retry 3 times
            try:
                r = remote(self.host, self.port, timeout=10)
                return r
            except Exception:
                time.sleep(1)
        return None

    def get_fresh_ciphertext(self):
        r = self.get_oracle()
        if not r:
            return None

        try:
            r.sendline(b'1')
            r.sendline(b'A' * 48)  # Send 3 blocks worth
            r.sendline(b'1')
            data = r.recvuntil(b'>')
            match = re.search(b"reads: ([A-Za-z0-9+/=]+)", data)
            if match:
                return b64decode(match.group(1))
        except Exception as e:
            print(f"Error getting ciphertext: {e}")
        finally:
            r.close()
        return None

    def oracle_query(self, ct):
        r = self.get_oracle()
        if not r:
            return False

        try:
            r.sendline(b'2')
            r.sendline(b64encode(ct))
            resp = r.recvline()
            return b'Valid' in resp
        except Exception:
            return False
        finally:
            r.close()

    def attack_byte(self, pos, cur_blocks):
        print(f"[*] Attacking byte position {pos}")

        # Get initial blocks
        blocks = [cur_blocks[i:i+self.block_size] for i in range(0, len(cur_blocks), self.block_size)]
        if len(blocks) < 3:
            return None

        for b in range(256):
            if b % 32 == 0:
                print(f"[*] Testing values {b}-{min(b+31, 255)}")

            modified = bytearray(blocks[1])
            modified[pos] = b

            test_ct = blocks[0] + bytes(modified) + blocks[2]

            if self.oracle_query(test_ct):
                print(f"[+] Found byte: {hex(b)} ({chr(b) if 32 <= b <= 126 else '?'})")
                return b

        return None

    def attack(self):
        print("[*] Starting POODLE attack...")
        decrypted = []

        retries = 0
        max_retries = 5

        while len(decrypted) < self.block_size and retries < max_retries:
            # Get fresh ciphertext
            ct = self.get_fresh_ciphertext()
            if not ct:
                retries += 1
                time.sleep(1)
                continue

            pos = self.block_size - 1 - len(decrypted)
            byte = self.attack_byte(pos, ct)

            if byte is not None:
                decrypted.append(byte)
                dec_text = bytes(decrypted)
                print(f"[+] Current decrypted ({len(decrypted)} bytes): {dec_text}")

                # Check for flag format
                if b'flag{' in dec_text and b'}' in dec_text:
                    start = dec_text.index(b'flag{')
                    end = dec_text.index(b'}', start) + 1
                    flag = dec_text[start:end].decode()
                    print(f"[!] Found flag: {flag}")
                    return flag

                retries = 0  # Reset retries on success
            else:
                retries += 1
                time.sleep(1)

        return None

if __name__ == '__main__':
    try:
        attacker = PoodleAttack()
        flag = attacker.attack()

        if flag:
            print(f"[+] Successfully extracted flag: {flag}")
            summary = f"Successfully implemented and executed the POODLE attack. The attack worked by exploiting the padding oracle vulnerability to decrypt the flag byte-by-byte. Final flag: {flag}"
        else:
