#!/usr/bin/env python3
from pwn import *
import base64
import time
import threading
from queue import Queue

context.log_level = 'error'

def create_connection():
    return remote('crypto.chal.csaw.io', 6000)

class FastPoodleOracle:
    def __init__(self):
        self.block_size = 16
        self.result_queue = Queue()
        self.stop_flag = False

    def get_single_ciphertext(self):
        try:
            r = create_connection()
            r.sendline(b'1')
            r.recvuntil(b'>')
            r.sendline(b'A' * 32)  # Two blocks padding
            r.recvuntil(b'>')
            r.sendline(b'1')
            r.recvuntil(b'reads: ')
            ct = base64.b64decode(r.recvline().strip())
            r.close()
            return ct
        except:
            return None

    def check_padding_oracle(self, ct):
        try:
            r = create_connection()
            r.sendline(b'2')
            r.recvuntil(b'>')
            r.sendline(base64.b64encode(ct))
            result = b'Valid' in r.recvline()
            r.close()
            return result
        except:
            return False

    def test_byte_worker(self, position, byte_value, blocks):
        if self.stop_flag:
            return

        try:
            modified = bytearray(blocks[1])
            modified[position] = byte_value
            test_ct = blocks[0] + bytes(modified) + blocks[2]

            if self.check_padding_oracle(test_ct):
                self.stop_flag = True
                self.result_queue.put(byte_value)
        except:
            pass

    def decrypt_byte(self, position):
        print(f"\rTrying to decrypt byte at position {position}...", end='', flush=True)

        while not self.stop_flag:
            ct = self.get_single_ciphertext()
            if not ct:
                continue

            blocks = [ct[i:i+self.block_size] for i in range(0, len(ct), self.block_size)]
            if len(blocks) < 3:
                continue

            threads = []
            self.stop_flag = False

            # Test bytes in parallel
            for b in range(256):
                if self.stop_flag:
                    break

                thread = threading.Thread(
                    target=self.test_byte_worker,
                    args=(position, b, blocks)
                )
                threads.append(thread)
                thread.start()

                # Limit concurrent threads
                if len(threads) >= 32:
                    for t in threads:
                        t.join()
                    threads = []

            # Wait for remaining threads
            for t in threads:
                t.join()

            # Check if we found the byte
            if not self.result_queue.empty():
                return self.result_queue.get()

            self.stop_flag = False
            time.sleep(0.1)

def attack():
    print("[*] Starting optimized POODLE attack...")
    oracle = FastPoodleOracle()
